 public sealed class RuleRow {public bool enabled=true;public string mode="literal",pattern="",replacement="";}
 public sealed class RuleConfig {public int schema_version=1;public bool enabled=true;public string revision=Guid.NewGuid().ToString();public RuleRow[] rules=new RuleRow[0];}
 public sealed class FormatResult {public string Name,Code;public bool Fallback;public string Status{get{return Fallback?"fallback:"+Code:"ok";}}}
 public sealed class RuleFailure:Exception {public readonly string Code;public RuleFailure(string code):base(code){Code=code;}}
 public static class Engine {
  public const int MaxBytes=131072,MaxName=512,MaxRules=32;
  static readonly UnicodeEncoding Utf16=new UnicodeEncoding(false,false,true);
  public static string DefaultRulesPath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ChatGPT-TitleSync","title-rules.json");}}
  public static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=MaxBytes,RecursionLimit=24};}
  public static byte[] ReadShared(string path,int maximum){using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(file.Length>maximum)throw new RuleFailure("FileTooLarge");using(var memory=new MemoryStream()){byte[] buffer=new byte[8192];while(true){int count=file.Read(buffer,0,Math.Min(buffer.Length,maximum-(int)memory.Length+1));if(count==0)break;memory.Write(buffer,0,count);if(memory.Length>maximum)throw new RuleFailure("FileTooLarge");}return memory.ToArray();}}}
  public static RuleConfig Parse(byte[] bytes){
   try{if(bytes.Length>MaxBytes)throw new RuleFailure("FileTooLarge");string text=new UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');var data=Json().DeserializeObject(text) as Dictionary<string,object>;
    if(data==null||!data.ContainsKey("schema_version")||!(data["schema_version"] is int)||(int)data["schema_version"]!=1||!(data["enabled"] is bool)||!(data["revision"] is string))throw new RuleFailure("InvalidConfig");Guid revision;if(!Guid.TryParse((string)data["revision"],out revision))throw new RuleFailure("InvalidConfig");
    var values=data["rules"] as object[];if(values==null||values.Length>MaxRules)throw new RuleFailure("InvalidConfig");var rows=new List<RuleRow>();
    foreach(object value in values){var row=value as Dictionary<string,object>;if(row==null||!(row["enabled"] is bool)||!(row["mode"] is string)||!(row["pattern"] is string)||!(row["replacement"] is string))throw new RuleFailure("InvalidConfig");rows.Add(new RuleRow{enabled=(bool)row["enabled"],mode=(string)row["mode"],pattern=(string)row["pattern"],replacement=(string)row["replacement"]});}
    var result=new RuleConfig{schema_version=1,enabled=(bool)data["enabled"],revision=(string)data["revision"],rules=rows.ToArray()};ValidateShape(result);return result;
   }catch(RuleFailure){throw;}catch{throw new RuleFailure("InvalidConfig");}
  }
  public static RuleConfig Load(string path){try{return Parse(ReadShared(path,MaxBytes));}catch(FileNotFoundException){return new RuleConfig();}catch(DirectoryNotFoundException){return new RuleConfig();}}
  public static void ValidateShape(RuleConfig config){if(config==null||config.schema_version!=1||config.rules==null||config.rules.Length>MaxRules)throw new RuleFailure("InvalidConfig");foreach(var row in config.rules){if(row==null||row.pattern==null||row.replacement==null||row.pattern.Length>512||row.replacement.Length>512||(row.mode!="literal"&&row.mode!="regex"))throw new RuleFailure("InvalidRule");try{Utf16.GetByteCount(row.pattern);Utf16.GetByteCount(row.replacement);}catch{throw new RuleFailure("InvalidRule");}if(row.enabled&&row.pattern.Length==0)throw new RuleFailure("EmptyPattern");}}
  sealed class Token {internal string Text;internal int Group=-1;}
  static List<Token> Template(string value,Regex regex){var output=new List<Token>();var literal=new StringBuilder();Action flush=delegate{if(literal.Length>0){output.Add(new Token{Text=literal.ToString()});literal.Length=0;}};
   for(int i=0;i<value.Length;i++){if(value[i]!='$'){literal.Append(value[i]);continue;}flush();if(++i>=value.Length)throw new RuleFailure("InvalidReplacement");if(value[i]=='$'){literal.Append('$');continue;}bool braces=value[i]=='{';if(braces&&++i>=value.Length)throw new RuleFailure("InvalidReplacement");int start=i;while(i<value.Length&&value[i]>='0'&&value[i]<='9')i++;int count=i-start;if(count<1||count>2)throw new RuleFailure("InvalidReplacement");int number=Int32.Parse(value.Substring(start,count),CultureInfo.InvariantCulture);if(braces){if(i>=value.Length||value[i]!='}')throw new RuleFailure("InvalidReplacement");}else i--;if(!regex.GetGroupNumbers().Contains(number))throw new RuleFailure("UnknownGroup");output.Add(new Token{Group=number});}flush();return output;}
  sealed class Compiled {internal RuleRow Rule;internal Regex Regex;internal List<Token> Tokens;}
  static List<Compiled> Compile(RuleConfig config){ValidateShape(config);var output=new List<Compiled>();foreach(var row in config.rules){if(!row.enabled)continue;var item=new Compiled{Rule=row};if(row.mode=="regex"){try{item.Regex=new Regex(row.pattern,RegexOptions.CultureInvariant,TimeSpan.FromMilliseconds(100));}catch{throw new RuleFailure("InvalidPattern");}item.Tokens=Template(row.replacement,item.Regex);}output.Add(item);}return output;}
  public static void Validate(RuleConfig config){Compile(config);}
  static void CheckName(string value,string failure){try{Utf16.GetByteCount(value??"");}catch{throw new RuleFailure(failure);}if(String.IsNullOrWhiteSpace(value)||value.Length>MaxName||value.Any(Char.IsControl)||String.Equals(value.Trim(),"ChatGPT",StringComparison.OrdinalIgnoreCase))throw new RuleFailure(failure);}
  public static FormatResult Apply(RuleConfig config,string raw){try{var timer=Stopwatch.StartNew();var compiled=Compile(config);CheckName(raw,"InvalidSource");string current=raw;foreach(var item in config.enabled?compiled:new List<Compiled>()){if(timer.ElapsedMilliseconds>=500)throw new RuleFailure("AggregateTimeout");
    if(item.Regex==null)current=current.Replace(item.Rule.pattern,item.Rule.replacement);
    else {var result=new StringBuilder();int previous=0;foreach(Match match in item.Regex.Matches(current)){if(timer.ElapsedMilliseconds>=500)throw new RuleFailure("AggregateTimeout");result.Append(current,previous,match.Index-previous);foreach(var token in item.Tokens){if(token.Group<0)result.Append(token.Text);else if(match.Groups[token.Group].Success)result.Append(match.Groups[token.Group].Value);}if(result.Length>MaxName)throw new RuleFailure("InvalidOutput");previous=match.Index+match.Length;}result.Append(current,previous,current.Length-previous);current=result.ToString();}
    CheckName(current,"InvalidOutput");if(timer.ElapsedMilliseconds>=500)throw new RuleFailure("AggregateTimeout");}
    return new FormatResult{Name=current,Code="ok"};
   }catch(RegexMatchTimeoutException){return new FormatResult{Name=raw,Fallback=true,Code="MatchTimeout"};}catch(RuleFailure error){return new FormatResult{Name=raw,Fallback=true,Code=error.Code};}catch{return new FormatResult{Name=raw,Fallback=true,Code="RuleError"};}}
  public static FormatResult FormatFile(string path,string raw){try{return Apply(Load(path),raw);}catch(RuleFailure error){return new FormatResult{Name=raw,Fallback=true,Code=error.Code};}catch{return new FormatResult{Name=raw,Fallback=true,Code="RulesReadFailed"};}}
  public static string ReadUtf16(string path){byte[] bytes=ReadShared(path,MaxBytes);if((bytes.Length&1)!=0)throw new IOException("Odd UTF16 input length");int start=bytes.Length>=2&&bytes[0]==255&&bytes[1]==254?2:0;return Utf16.GetString(bytes,start,bytes.Length-start);}
  public static void WriteUtf16(string path,string text){File.WriteAllBytes(path,Utf16.GetBytes(text??""));}
  public static byte[] Serialize(RuleConfig config){return new UTF8Encoding(false).GetBytes(Json().Serialize(config));}
  public static void Save(string path,RuleConfig config){Validate(config);config.revision=Guid.NewGuid().ToString();byte[] bytes=Serialize(config);if(bytes.Length>MaxBytes)throw new RuleFailure("FileTooLarge");Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";byte[] before=File.Exists(path)?ReadShared(path,MaxBytes):null;
   try{File.WriteAllBytes(temp,bytes);if(before==null)File.Move(temp,path);else File.Replace(temp,path,null);if(!ReadShared(path,MaxBytes).SequenceEqual(bytes)){if(before==null)File.Delete(path);else File.WriteAllBytes(path,before);throw new IOException("Rule save readback failed");}}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static string[] ReadSnapshot(string path){byte[] bytes=ReadShared(path,MaxBytes);using(var memory=new MemoryStream(bytes))using(var reader=new BinaryReader(memory,Utf16)){if(bytes.Length<8||Encoding.ASCII.GetString(reader.ReadBytes(4))!="CTS1")throw new RuleFailure("InvalidSnapshot");uint count=reader.ReadUInt32();if(count>128)throw new RuleFailure("InvalidSnapshot");var names=new List<string>();for(int i=0;i<count;i++){uint length=reader.ReadUInt32();if(length>MaxName||memory.Length-memory.Position<length*2)throw new RuleFailure("InvalidSnapshot");string name=Utf16.GetString(reader.ReadBytes((int)length*2));CheckName(name,"InvalidSnapshot");names.Add(name);}if(memory.Position!=memory.Length)throw new RuleFailure("InvalidSnapshot");return names.ToArray();}}
 }

 public static class RuleProcess {
  static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
  public static FormatResult Run(string executable,byte[] rules,string raw,string state){return Run(executable,rules,raw,state,null,null);}
  public static FormatResult Run(string executable,byte[] rules,string raw,string state,Action<Process> started,Action<Process> stopped){string folder=Path.Combine(state,"rule-worker-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string input=Path.Combine(folder,"input.bin"),output=Path.Combine(folder,"output.bin"),status=Path.Combine(folder,"status.txt"),config=Path.Combine(folder,"rules.json");Process child=null;
   try{Engine.WriteUtf16(input,raw);if(rules!=null)File.WriteAllBytes(config,rules);var start=new ProcessStartInfo(executable,"--format --rules "+Quote(config)+" --input "+Quote(input)+" --output "+Quote(output)+" --status "+Quote(status)){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(executable)};var deadline=Stopwatch.StartNew();child=Process.Start(start);IntPtr pinned=child.Handle;long born=child.StartTime.ToUniversalTime().Ticks;if(started!=null)started(child);
    if(!child.WaitForExit(Math.Max(0,1500-(int)deadline.ElapsedMilliseconds))){if(!child.HasExited&&child.StartTime.ToUniversalTime().Ticks==born)child.Kill();child.WaitForExit(500);return new FormatResult{Name=raw,Fallback=true,Code="WorkerTimeout"};}
    if((child.ExitCode!=0&&child.ExitCode!=2)||!File.Exists(output)||!File.Exists(status))return new FormatResult{Name=raw,Fallback=true,Code="WorkerFailed"};string code=Encoding.ASCII.GetString(Engine.ReadShared(status,128)).Trim();string name=Engine.ReadUtf16(output);if(name.Length>Engine.MaxName)return new FormatResult{Name=raw,Fallback=true,Code="InvalidWorkerOutput"};if(child.ExitCode==0&&code=="ok")return new FormatResult{Name=name,Code="ok"};if(child.ExitCode==2&&code.StartsWith("fallback:",StringComparison.Ordinal)&&name==raw)return new FormatResult{Name=raw,Fallback=true,Code=code.Substring(9)};return new FormatResult{Name=raw,Fallback=true,Code="InvalidWorkerStatus"};
   }catch{return new FormatResult{Name=raw,Fallback=true,Code="WorkerIO"};}finally{if(child!=null){if(stopped!=null)stopped(child);child.Dispose();}foreach(string file in new[]{input,output,status,config})try{if(File.Exists(file))File.Delete(file);}catch{}try{Directory.Delete(folder,false);}catch{}}
  }
 }
