  readonly object gate=new object();readonly string executable,rulesPath,stateDirectory;readonly IdentityInspector inspectIdentity;readonly Dictionary<string,FormatResult> cache=new Dictionary<string,FormatResult>(StringComparer.Ordinal);readonly HashSet<string> pending=new HashSet<string>(StringComparer.Ordinal);sealed class Job{internal string Raw,Signature;internal byte[] Bytes;}readonly Queue<Job> queue=new Queue<Job>();readonly HashSet<Process> workers=new HashSet<Process>();bool draining;string signature="",snapshotSignature="";byte[] ruleBytes;bool identity=true,disposed;DateTime nextPoll=DateTime.MinValue;long displayRevision;
