  public Process OpenEditor(string help){if(!Path.IsPathRooted(help)||!File.Exists(help))throw new FileNotFoundException("Packaged local name-replacement help was not found");return Process.Start(new ProcessStartInfo(executable,"--edit --rules \""+rulesPath+"\" --sources \""+SourcesPath+"\" --help \""+Path.GetFullPath(help)+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(executable)});}
