   debounce.Interval=250;debounce.Tick+=delegate{debounce.Stop();bool saveRequested=pendingSave;pendingSave=false;PreviewDraft(saveRequested);};sourceTimer.Interval=2000;sourceTimer.Tick+=delegate{ReadSources(false);};sourceTimer.Start();enabled.CheckedChanged+=delegate{Changed();};grid.CellValueChanged+=delegate{Changed();};grid.RowsRemoved+=delegate{Changed();};grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.DataError+=delegate(object sender,DataGridViewDataErrorEventArgs args){args.ThrowException=false;message.Text="Invalid cell / 单元格无效";};sample.TextChanged+=delegate{Changed();};sources.SelectedIndexChanged+=delegate{if(sources.SelectedItem!=null)sample.Text=Convert.ToString(sources.SelectedItem);};ReadSources(true);Changed();FormClosed+=delegate{closing=true;generation++;lock(previewGate){if(previewChild!=null)try{if(!previewChild.HasExited)previewChild.Kill();}catch{}}debounce.Dispose();sourceTimer.Dispose();};
