  RuleConfig Draft(){grid.EndEdit();var rows=grid.Rows.Cast<DataGridViewRow>().Select(row=>new RuleRow{enabled=Convert.ToBoolean(row.Cells[0].Value??false),mode=Convert.ToString(row.Cells[1].Value),pattern=Convert.ToString(row.Cells[2].Value??""),replacement=Convert.ToString(row.Cells[3].Value??"")}).ToArray();return new RuleConfig{enabled=enabled.Checked,rules=rows};}
  void Changed(){generation++;debounce.Stop();debounce.Start();}
  void EditRow(string action){if(action=="add"){if(grid.Rows.Count<32)grid.Rows.Add(true,"literal","","");}else if(grid.CurrentRow!=null){int index=grid.CurrentRow.Index;if(action=="remove")grid.Rows.RemoveAt(index);else{int next=index+(action=="up"?-1:1);if(next>=0&&next<grid.Rows.Count){object[] values=grid.Rows[index].Cells.Cast<DataGridViewCell>().Select(cell=>cell.Value).ToArray();grid.Rows.RemoveAt(index);grid.Rows.Insert(next,values);grid.CurrentCell=grid.Rows[next].Cells[2];}}}Changed();}
  void ReadSources(bool force){try{DateTime stamp=File.GetLastWriteTimeUtc(sourcesPath);if(!force&&stamp==snapshotStamp)return;var names=Engine.ReadSnapshot(sourcesPath);string selected=Convert.ToString(sources.SelectedItem);sources.Items.Clear();sources.Items.AddRange(names.Distinct(StringComparer.Ordinal).Cast<object>().ToArray());if(sources.Items.Contains(selected))sources.SelectedItem=selected;snapshotStamp=stamp;snapshotInfo.Text="Snapshot / 快照: "+stamp.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss")+" · "+names.Length+" windows / 窗口 (no new ChatGPT read / 不额外读取)";}catch{sources.Items.Clear();snapshotInfo.Text="No valid snapshot; manual example remains available. / 无有效快照，可手工输入示例。";}}
  static bool InvalidSave(string code){return new[]{"InvalidConfig","InvalidRule","EmptyPattern","InvalidPattern","InvalidReplacement","UnknownGroup","FileTooLarge","RulesReadFailed","WorkerTimeout","WorkerFailed","WorkerIO","InvalidWorkerStatus"}.Contains(code);}
  void PreviewDraft(bool saving){if(busy){pendingSave|=saving;debounce.Start();return;}RuleConfig draft;string raw=sample.Text;int expected;try{draft=Draft();Engine.ValidateShape(draft);expected=generation;}catch(Exception error){message.Text=error.Message;return;}busy=true;message.Text=saving?"Validating save / 正在验证保存…":"Previewing local example / 正在预览手工示例…";byte[] bytes=Engine.Serialize(draft);
   ThreadPool.QueueUserWorkItem(delegate{var result=RuleProcess.Run(executable,bytes,raw,tempDirectory,delegate(Process child){lock(previewGate){previewChild=child;if(closing&&!child.HasExited)child.Kill();}},delegate(Process child){lock(previewGate){if(previewChild==child)previewChild=null;}});if(closing)return;try{BeginInvoke((Action)delegate{busy=false;if(closing)return;if(pendingSave){pendingSave=false;PreviewDraft(true);return;}if(expected!=generation){debounce.Start();return;}preview.Text=result.Name;message.Text=result.Fallback?"Original name preserved / 保留原名: "+result.Code:"Preview only; Save applies rules. / 仅预览，保存后应用。";if(saving&&!InvalidSave(result.Code)){try{Engine.Save(rulePath,draft);Close();}catch(Exception error){message.Text="Save failed / 保存失败: "+error.Message;}}});}catch{}});
  }
  void SaveDraft(){PreviewDraft(true);}
  public static RuleSuggestion[] SuggestFor(string raw,string selected){var output=new List<RuleSuggestion>();Action<string,string,string> add=delegate(string explanation,string pattern,string replacement){var config=new RuleConfig{rules=new[]{new RuleRow{mode="regex",pattern=pattern,replacement=replacement}}};var result=Engine.Apply(config,raw);if(!result.Fallback&&result.Name!=raw)output.Add(new RuleSuggestion{Explanation=explanation,Pattern=pattern,Replacement=replacement,Result=result.Name});};
   if(!String.IsNullOrEmpty(selected)){int start=raw.IndexOf(selected,StringComparison.Ordinal);if(start>=0)add("Keep selected text / 保留所选文本",@"\A"+Regex.Escape(raw.Substring(0,start))+"("+Regex.Escape(selected)+")"+Regex.Escape(raw.Substring(start+selected.Length))+@"\z","$1");}
   foreach(char separator in new[]{'|','｜',':','：','—','-','/'}){int index=raw.IndexOf(separator);if(index>0&&index<raw.Length-1){add("Remove example prefix / 去掉示例前缀",@"\A"+Regex.Escape(raw.Substring(0,index+1))+@"\s*","");add("Keep after separator / 保留分隔符后内容",@"\A.*?"+Regex.Escape(separator.ToString())+@"\s*(.+)\z","$1");break;}}
   foreach(string pair in new[]{"()","[]","{}","<>","【】","「」","『』"}){int start=raw.IndexOf(pair[0]),end=raw.LastIndexOf(pair[1]);if(start>=0&&end>start+1)add("Keep paired content / 保留成对符号内部",@"\A.*?"+Regex.Escape(pair[0].ToString())+"(.+?)"+Regex.Escape(pair[1].ToString())+@".*\z","$1");}return output.ToArray();}
  void Suggest(){string raw=sample.Text,selected=sample.SelectedText;int expected=generation;ThreadPool.QueueUserWorkItem(delegate{var results=SuggestFor(raw,selected);if(closing)return;try{BeginInvoke((Action)delegate{if(closing||expected!=generation)return;suggestions.Items.Clear();foreach(var suggestion in results)suggestions.Items.Add(suggestion);message.Text="Suggestions are drafts; select Use rule, then Save. / 建议不会自动应用，须先使用再保存。";});}catch{}});}
