  [STAThread]public static int Main(string[] args){try{bool format=args.Contains("--format"),edit=args.Contains("--edit");if(format==edit)return 3;var values=new Dictionary<string,string>(StringComparer.Ordinal);for(int i=0;i<args.Length;i++){if(args[i]=="--format"||args[i]=="--edit")continue;if(!args[i].StartsWith("--")||i+1>=args.Length||values.ContainsKey(args[i]))return 3;values.Add(args[i],args[++i]);}foreach(string path in values.Values)if(!Path.IsPathRooted(path))return 3;
    if(format){if(values.Count!=4||!values.ContainsKey("--rules")||!values.ContainsKey("--input")||!values.ContainsKey("--output")||!values.ContainsKey("--status"))return 3;var paths=values.Values.Select(Path.GetFullPath).ToArray();if(paths.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=4)return 3;string raw=Engine.ReadUtf16(values["--input"]);var result=Engine.FormatFile(values["--rules"],raw);Engine.WriteUtf16(values["--output"],result.Name);File.WriteAllText(values["--status"],result.Status,Encoding.ASCII);return result.Code=="RulesReadFailed"?3:(result.Fallback?2:0);}
    if(values.Count!=3||!values.ContainsKey("--rules")||!values.ContainsKey("--sources")||!values.ContainsKey("--help"))return 3;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var editor=new RulesEditor(values["--rules"],values["--sources"],values["--help"]))Application.Run(editor);return 0;
